/**
 * Build the WebAssembly kernels.
 *
 * Purpose: compile the modules in `assembly/` with SIMD and embed each binary
 * in `src/wasm/` as base64. The generated file is committed, so using
 * or testing the solver never needs the AssemblyScript compiler — only
 * changing a kernel does.
 *
 *   npm run build:wasm
 */

import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
const scratch = mkdtempSync(join(tmpdir(), 'kernels-'));

/** Each module: its source, the generated file, the constant it exports, and what it is. */
const MODULES = [
	{ source: 'assembly/kernels.ts', out: 'kernels.ts', name: 'KERNELS_WASM', what: 'The SIMD kernels' },
	{ source: 'assembly/engine.ts', out: 'engine.ts', name: 'ENGINE_WASM', what: 'The traversal engine' },
];

try {
	for (const { source, out, name, what } of MODULES) {
		const wasm = join(scratch, `${name}.wasm`);
		execFileSync(
			join(root, 'node_modules', '.bin', 'asc'),
			[source, '--enable', 'simd', '--enable', 'bulk-memory', '-O3', '--runtime', 'stub', '--importMemory', '--noAssert', '-o', wasm],
			{ cwd: root, stdio: 'inherit' },
		);
		const bytes = readFileSync(wasm);
		const text = `// Generated by scripts/build-wasm.ts from ${source}. Do not edit.
/** ${what}, ${bytes.length} bytes of WebAssembly. */
export const ${name} = '${bytes.toString('base64')}';
`;
		writeFileSync(join(root, 'src', 'wasm', out), text);
		console.log(`src/wasm/${out}: ${bytes.length} bytes`);
	}
} finally {
	rmSync(scratch, { recursive: true, force: true });
}
